def transform(wb):
    ws = wb["Sheet1"]
    endings = ["ING", "ERS", "ATE", "EST", "ONE", "IER", "ILY"]
    words = []
    for r in range(2, 5001):
        v = ws.cell(row=r, column=1).value
        if v is not None:
            s = str(v).strip().upper()
            if s:
                words.append(s)
    words = sorted(words)
    groups = {}
    for e in endings:
        groups[e] = []
    for w in words:
        if len(w) >= 5:
            e = w[-3:]
            if e in groups:
                t = w[4] + w[:4] + w[5:]
                groups[e].append((t, w))
    for r in range(2, 5001):
        ws.cell(row=r, column=3).value = None
        ws.cell(row=r, column=4).value = None
    row = 2
    for e in endings:
        if row > 5000:
            break
        for pair in groups[e]:
            if row > 5000:
                break
            ws.cell(row=row, column=3).value = pair[0]
            ws.cell(row=row, column=4).value = pair[1]
            row = row + 1
